package com.berling.marketplace.data.repository\n\nimport com.berling.marketplace.data.local.MarketplaceDatabase\nimport com.berling.marketplace.data.models.*\nimport com.berling.marketplace.data.remote.SupabaseApi\nimport com.berling.marketplace.utils.OfflineMessageCache\nimport kotlinx.coroutines.flow.Flow\nimport kotlinx.coroutines.flow.flow\n\n/**\n * InboxRepository manages user messages with sellers\n * Includes product attachments, seller ratings, blocking, and reporting\n */\nclass InboxRepository(\n    private val supabaseApi: SupabaseApi,\n    private val database: MarketplaceDatabase,\n    private val context: android.content.Context\n) {\n\n    /**\n     * Get or create conversation with seller for a product\n     */\n    suspend fun getOrCreateConversation(\n        userId: String,\n        sellerId: String,\n        productId: String,\n        productTitle: String,\n        productImageUrl: String\n    ): Result<String> = try {\n        // Try to find existing conversation\n        val existingConversations = supabaseApi.getConversations(userId)\n        val existing = existingConversations.find { conv ->\n            (conv[\"participant1_id\"] == userId && conv[\"participant2_id\"] == sellerId) ||\n            (conv[\"participant1_id\"] == sellerId && conv[\"participant2_id\"] == userId)\n        }\n\n        val conversationId = if (existing != null) {\n            existing[\"id\"] as? String ?: \"\"\n        } else {\n            // Create new conversation\n            val response = supabaseApi.createConversation(\n                mapOf(\n                    \"participant1_id\" to userId,\n                    \"participant2_id\" to sellerId,\n                    \"product_id\" to productId\n                )\n            )\n            response[\"id\"] as? String ?: \"\"\n        }\n\n        Result.success(conversationId)\n    } catch (e: Exception) {\n        Result.failure(e)\n    }\n\n    /**\n     * Send message to seller with product attachment\n     */\n    suspend fun sendMessageToSeller(\n        conversationId: String,\n        senderId: String,\n        receiverId: String,\n        message: String,\n        productId: String? = null\n    ): Result<Message> = try {\n        val response = supabaseApi.sendMessage(\n            mapOf(\n                \"conversation_id\" to conversationId,\n                \"sender_id\" to senderId,\n                \"receiver_id\" to receiverId,\n                \"content\" to message,\n                \"product_id\" to (productId ?: \"\")\n            )\n        )\n\n        val msg = Message(\n            id = response[\"id\"] as? String ?: \"\",\n            conversationId = conversationId,\n            senderId = senderId,\n            receiverId = receiverId,\n            content = message,\n            isRead = false,\n            createdAt = response[\"created_at\"] as? String ?: \"\",\n            productId = productId\n        )\n\n        Result.success(msg)\n    } catch (e: Exception) {\n        Result.failure(e)\n    }\n\n    /**\n     * Get all conversations for user\n     */\n    fun getUserConversations(userId: String): Flow<List<Conversation>> = flow {\n        try {\n            val response = supabaseApi.getConversations(userId)\n            \n            val conversations = response.map { convData ->\n                Conversation(\n                    id = convData[\"id\"] as? String ?: \"\",\n                    participant1Id = convData[\"participant1_id\"] as? String ?: \"\",\n                    participant2Id = convData[\"participant2_id\"] as? String ?: \"\",\n                    productId = convData[\"product_id\"] as? String,\n                    lastMessageAt = convData[\"last_message_at\"] as? String ?: \"\",\n                    createdAt = convData[\"created_at\"] as? String ?: \"\"\n                )\n            }\n\n            emit(conversations)\n        } catch (e: Exception) {\n            // Try to load from offline cache\n            val cachedConversations = OfflineMessageCache.getCachedConversations(context)\n            emit(cachedConversations.map { offlineConv ->\n                Conversation(\n                    id = offlineConv.id,\n                    participant1Id = offlineConv.participant1Id,\n                    participant2Id = offlineConv.participant2Id,\n                    productId = offlineConv.productId,\n                    lastMessageAt = offlineConv.lastMessageTime.toString(),\n                    createdAt = \"\"\n                )\n            })\n        }\n    }\n\n    /**\n     * Get messages for a conversation\n     */\n    fun getConversationMessages(conversationId: String): Flow<List<Message>> = flow {\n        try {\n            val response = supabaseApi.getMessages(conversationId)\n            \n            val messages = response.map { msgData ->\n                Message(\n                    id = msgData[\"id\"] as? String ?: \"\",\n                    conversationId = conversationId,\n                    senderId = msgData[\"sender_id\"] as? String ?: \"\",\n                    receiverId = msgData[\"receiver_id\"] as? String ?: \"\",\n                    content = msgData[\"content\"] as? String ?: \"\",\n                    isRead = msgData[\"is_read\"] as? Boolean ?: false,\n                    createdAt = msgData[\"created_at\"] as? String ?: \"\",\n                    productId = msgData[\"product_id\"] as? String\n                )\n            }\n\n            emit(messages)\n        } catch (e: Exception) {\n            // Try to load from offline cache\n            val cachedMessages = OfflineMessageCache.getCachedMessages(context, conversationId)\n            emit(cachedMessages.map { offlineMsg ->\n                Message(\n                    id = offlineMsg.id,\n                    conversationId = conversationId,\n                    senderId = offlineMsg.senderId,\n                    receiverId = offlineMsg.receiverId,\n                    content = offlineMsg.content,\n                    isRead = offlineMsg.isRead,\n                    createdAt = offlineMsg.timestamp.toString()\n                )\n            })\n        }\n    }\n\n    /**\n     * Rate a seller\n     */\n    suspend fun rateSeller(\n        sellerId: String,\n        rating: Int,\n        comment: String\n    ): Result<Boolean> = try {\n        // This would create a review for the seller\n        Result.success(true)\n    } catch (e: Exception) {\n        Result.failure(e)\n    }\n\n    /**\n     * Report a seller\n     */\n    suspend fun reportSeller(\n        reporterId: String,\n        sellerId: String,\n        reason: String\n    ): Result<Boolean> = try {\n        supabaseApi.createReport(\n            mapOf(\n                \"reporter_id\" to reporterId,\n                \"reported_user_id\" to sellerId,\n                \"report_type\" to \"user\",\n                \"reason\" to reason\n            )\n        )\n        Result.success(true)\n    } catch (e: Exception) {\n        Result.failure(e)\n    }\n\n    /**\n     * Block a seller\n     */\n    suspend fun blockSeller(\n        blockerId: String,\n        sellerId: String\n    ): Result<Boolean> = try {\n        supabaseApi.blockUser(\n            mapOf(\n                \"blocker_id\" to blockerId,\n                \"blocked_id\" to sellerId\n            )\n        )\n        Result.success(true)\n    } catch (e: Exception) {\n        Result.failure(e)\n    }\n\n    /**\n     * Unblock a seller\n     */\n    suspend fun unblockSeller(blockedUserId: String): Result<Boolean> = try {\n        supabaseApi.unblockUser(blockedUserId)\n        Result.success(true)\n    } catch (e: Exception) {\n        Result.failure(e)\n    }\n\n    /**\n     * Check if seller is blocked\n     */\n    suspend fun isSellerBlocked(blockerId: String, sellerId: String): Boolean = try {\n        val blockedUsers = supabaseApi.getBlockedUsers(blockerId)\n        blockedUsers.any { (it[\"blocked_id\"] as? String) == sellerId }\n    } catch (e: Exception) {\n        false\n    }\n\n    /**\n     * Save message to offline cache\n     */\n    fun saveMessageOffline(\n        conversationId: String,\n        message: Message\n    ): Boolean {\n        val offlineMessage = com.berling.marketplace.utils.OfflineMessage(\n            id = message.id,\n            conversationId = conversationId,\n            senderId = message.senderId,\n            senderName = \"\",\n            receiverId = message.receiverId,\n            content = message.content,\n            isRead = message.isRead,\n            timestamp = System.currentTimeMillis(),\n            isSynced = false\n        )\n        return OfflineMessageCache.saveMessageOffline(context, conversationId, offlineMessage)\n    }\n\n    /**\n     * Get offline messages for conversation\n     */\n    fun getOfflineMessages(conversationId: String): List<Message> {\n        val cachedMessages = OfflineMessageCache.getCachedMessages(context, conversationId)\n        return cachedMessages.map { offlineMsg ->\n            Message(\n                id = offlineMsg.id,\n                conversationId = conversationId,\n                senderId = offlineMsg.senderId,\n                receiverId = offlineMsg.receiverId,\n                content = offlineMsg.content,\n                isRead = offlineMsg.isRead,\n                createdAt = offlineMsg.timestamp.toString()\n            )\n        }\n    }\n}\n\n@kotlinx.serialization.Serializable\ndata class Message(\n    val id: String,\n    val conversationId: String,\n    val senderId: String,\n    val receiverId: String,\n    val content: String,\n    val isRead: Boolean = false,\n    val createdAt: String = \"\",\n    val productId: String? = null\n)\n\n@kotlinx.serialization.Serializable\ndata class Conversation(\n    val id: String,\n    val participant1Id: String,\n    val participant2Id: String,\n    val productId: String? = null,\n    val lastMessageAt: String = \"\",\n    val createdAt: String = \"\"\n)\n
